  stk rsegs m lo (bv_unsigned sp) ->
  rw_cells rsegs m PGOT_FINI [C8 (Z_to_bv 64 0x26420); C8 (Z_to_bv 64 PFINI_ARRAY)] ->   (* [comment removed for export] *)
  rw_cells rsegs m PFINI_ARRAY [C8 (Z_to_bv 64 0x12ca0)] ->                              (* [comment removed for export] *)
